        d_to_opp = abs(ox - nx) + abs(oy - ny)
        if behind:
            if res is not None:
                d_to_res = abs(res[0] - nx) + abs(res[1] - ny)
                return -d_to_res + 0.01 * d_to_opp
            return 0.01 * d_to_opp
        return d_to_opp

    best = None
    best_val = -10**18
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not inb(nx, ny):
            continue
        if (nx, ny) in obs:
            continue
        val = eval_move(nx, ny)
        if val > best_val or (val == best_val and (dx, dy) < best):
            best_val = val
            best = (dx, dy)

